using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;
class DedicatedA17Host{
 static readonly string root=AppDomain.CurrentDomain.BaseDirectory,log=Path.Combine(root,"dedicated-host.log");static int instancePort,supervisorPid,capacity=100,bots=95;static string hostRoot,hostName;static long supervisorStartTicks;static Form f;static Timer timer;static Task<object> auth;static DateTime since;static int phase;static Assembly a;
 static object Get(string n){return f.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(f);}static void Set(string n,object v){f.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).SetValue(f,v);}static object Call(string n,params object[] v){return f.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,v);}static void Cmd(string n,Dictionary<string,string> v){Call("NativeCommand",n,v);}static void Cmd(string n){Cmd(n,new Dictionary<string,string>());}static void Log(string s){File.AppendAllText(log,DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+" "+s+"\r\n");}static void Go(int n){phase=n;since=DateTime.UtcNow;File.WriteAllText(Path.Combine(root,"worker-state.txt"),n==1?"opening":n==2?"waiting":n==3?"starting":n==4?"playing":n==5?"draining":"authenticating");}static bool Age(int s){return(DateTime.UtcNow-since).TotalSeconds>s;}
 static object Authenticate(){var t=a.GetType("OgbgCredentialVault",true);var vault=Activator.CreateInstance(t,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public,null,new object[]{hostRoot},null);object[] pair={null,null};if(!(bool)t.GetMethod("TryLoad",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(vault,pair))throw new Exception("Saved NET login is unavailable");try{var c=a.GetType("OgbgAuthClient",true);var client=Activator.CreateInstance(c,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public,null,new object[]{new Uri("http://217.199.220.41:3001/")},null);return c.GetMethod("Login",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(client,pair);}finally{pair[0]=pair[1]=null;}}
 static Dictionary<string,string> HostOptions(){return new Dictionary<string,string>{{"name",hostName},{"password",""},{"capacity",capacity.ToString()},{"bots",bots.ToString()},{"minimum","1"},{"map","Miramar"},{"mode","Solo"},{"camera","FPP"},{"autoJoin","0"},{"dedicated","1"},{"visible","1"},{"late","1"},{"quick","1"},{"gamePort",instancePort.ToString()},{"lobbyPort",instancePort.ToString()}};}
 static void Stop(string why){Log("STOP: "+why);try{File.WriteAllText(Path.Combine(root,"worker-state.txt"),"stopped");}catch{}try{Cmd("stop");}catch{}try{Call("CloseRoomConnection");Set("_exitRequested",true);f.Close();}catch{}timer.Stop();Application.ExitThread();}
 static bool SupervisorAlive(){try{using(var process=System.Diagnostics.Process.GetProcessById(supervisorPid))return !process.HasExited&&process.StartTime.ToUniversalTime().Ticks==supervisorStartTicks;}catch(Exception){return false;}}
 static void Tick(object o,EventArgs e){try{if(!SupervisorAlive()){Stop("supervisor exited");return;}if(File.Exists(Path.Combine(root,"stop-dedicated.flag"))){Stop("operator requested shutdown");return;}switch(phase){
 case 0:if(!auth.IsCompleted){if(Age(45))throw new Exception("account login timed out");break;}if(auth.IsFaulted)throw new Exception("account login failed: "+auth.Exception.GetBaseException().Message);Set("_onlineIdentity",auth.Result);Set("_netMode",true);Call("NativePublish");Cmd("host",HostOptions());Log("Opening Quick Match waiting room: "+capacity+" places, "+bots+" bots, map decided by vote; late join enabled");Go(1);break;
 case 1:if(!(bool)Get("_roomConnected")||!(bool)Get("_appearanceSynced")){if(Age(35))throw new Exception("room did not start");break;}if(!(bool)Get("_dedicatedServer"))throw new Exception("dedicated mode not active");Log("READY: Quick Match room waiting for a map vote");Go(2);break;
 case 2:if(!(bool)Get("_roomConnected"))throw new Exception("lobby connection lost");if((bool)Get("_roomStarting")){Log("Accepted vote is starting the selected map");Go(3);}break;
 case 3:if(!(bool)Get("_roomConnected"))throw new Exception("lobby connection lost");if((bool)Get("_serverReady")){Log("READY: voted game server online");Go(4);}else if(!(bool)Get("_roomStarting")){Log("Match could not start; waiting for a new vote");Go(2);}else if(Age(240))throw new Exception("voted game server did not become ready");break;
 case 4:if(!(bool)Get("_roomConnected"))throw new Exception("lobby connection lost");if(!(bool)Get("_serverReady")&&!(bool)Get("_roomStarting")){Log("Game stopped; waiting for final room notifications");Go(5);}break;
 case 5:if(Age(5))Stop("match ended; releasing instance");break;
 }}catch(Exception ex){Stop("ERROR: "+ex.GetBaseException().Message);}}
 [STAThread]static void Main(){File.WriteAllText(log,"");try{if(!Int32.TryParse(File.ReadAllText(Path.Combine(root,"quick-port.txt")).Trim(),out instancePort)||instancePort<8000||instancePort>10000)throw new Exception("Invalid instance port");hostRoot=File.ReadAllText(Path.Combine(root,"quick-host-root.txt")).Trim();hostName=File.ReadAllText(Path.Combine(root,"quick-host-name.txt")).Trim();if(!Int32.TryParse(File.ReadAllText(Path.Combine(root,"quick-capacity.txt")).Trim(),out capacity)||!Int32.TryParse(File.ReadAllText(Path.Combine(root,"quick-bots.txt")).Trim(),out bots)||capacity<1||capacity>100||bots<0||bots>95||bots>=capacity)throw new Exception("Invalid dedicated slots or bots");if(String.IsNullOrEmpty(hostRoot)||String.IsNullOrEmpty(hostName)||hostName.Length>32)throw new Exception("Invalid host configuration");string[] parent=File.ReadAllText(Path.Combine(root,"supervisor-identity.txt")).Trim().Split('|');if(parent.Length!=2||!Int32.TryParse(parent[0],out supervisorPid)||!Int64.TryParse(parent[1],out supervisorStartTicks))throw new Exception("Invalid supervisor identity");Environment.SetEnvironmentVariable("PUBG2019_LAN_TEST","1");Application.EnableVisualStyles();a=Assembly.LoadFrom(Path.Combine(root,"PUBG2019Launcher.exe"));f=(Form)Activator.CreateInstance(a.GetType("LauncherForm",true));timer=new Timer{Interval=1000};timer.Tick+=Tick;f.Shown+=delegate{auth=Task<object>.Run((Func<object>)Authenticate);Go(0);timer.Start();};Application.Run(f);}catch(Exception e){Log("ERROR: "+e.GetBaseException().Message);Environment.ExitCode=1;}}
}
